// Zusätzliche Sprach-Overlays für Loc (pt/ja/zh/ru/id). In eine EIGENE Datei ausgelagert,
// damit der Release-Optimizer nicht an einem einzigen Riesen-Literal minutenlang kaut
// (gleicher Grund wie das _t1/_t2/_t3-Split in Loc.swift). Fallback je Key: Englisch
// (siehe Loc.t). Referenziert aus Loc.t als ptOverlay/jaOverlay/zhOverlay/ruOverlay/idOverlay.

// Portugiesisch-Overlay (532 Keys). Fallback: Englisch.
// In 10 Bloecke zerlegt: EIN Literal mit 543 Eintraegen ist fuer den
// Swift-Type-Checker EIN Ausdruck, dessen Kosten ueberproportional wachsen (der Build hing
// minutenlang genau in dieser Datei). Zusammengefuehrt beim ersten Zugriff.
    // Spots-Suche (16.09.2026) — aus web/src/i18n/locales/pt.ts.
    private let _ptOverlaySpotsSuche: [String: String] = [
        "home.spotPick": "Escolha um spot …",
        "spots.onlyWithNotes": "Só com descrição",
        "spots.autoHint": "Você não precisa criar spots: eles aparecem automaticamente assim que alguém envia uma sessão em um lugar novo. Os nomes de lugares e águas vêm do OpenStreetMap — logo após o envio, o nome pode demorar alguns minutos.",
        "profile.foilsSports": "Meus foils e esportes",
    ]
let ptOverlay: [String: String] = {
    var d: [String: String] = [:]
    for p in [_ptOverlaySpotsSuche, _ptOverlayP1, _ptOverlayP1s2, _ptOverlayP2, _ptOverlayP2s2, _ptOverlayP3, _ptOverlayP3s2, _ptOverlayP4, _ptOverlayP4s2, _ptOverlayP5, _ptOverlayP5s2, _ptOverlayP6, _ptOverlayP6s2, _ptOverlayP7, _ptOverlayP7s2, _ptOverlayP8, _ptOverlayP8s2, _ptOverlayP9, _ptOverlayP9s2, _ptOverlayP10, _ptOverlayP10s2, _ptOverlayP11, _ptOverlayP11s2, _ptOverlayP11s2r1, _ptOverlayP11s2r2, _ptOverlayP11s8, _ptOverlayP11s7, _ptOverlayP11s3, _ptOverlayP11s4, _ptOverlayP11s5, _ptOverlayP11s6] { d.merge(p) { a, _ in a } }
    return d
}()

