    "imp.hostTitle": "サーバーとホスティング",
    "imp.host1": "pumpfoil.org のサーバーは <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> が運用しています。同社の代表者がこのプロジェクトの運営者で、SmartKomm はサーバーを<b>無償</b>で提供しています。",
    "imp.host2": "サーバーは <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b> にあります。Hetzner との間で<b>GDPR 第28条に基づくデータ処理契約</b>を締結しています。",
    "imp.fbTitle": "Facebook サインイン（「Facebook で続ける」）",
    "imp.fbIntro": "Facebook アカウントでサインインした場合、当サイトは次のデータのみを取り扱います。",
    "imp.fb1": "<b>取得:</b> メールアドレス、名（ファーストネーム）、Facebook ユーザー ID。姓とプロフィール写真は取得しません。",
    "imp.fb2": "<b>利用:</b> Pumpfoil アカウントの作成とサインイン、およびアプリ内での名の表示のみのため。",
    "imp.fb3": "その他の Facebook データには<b>一切アクセスしません</b>。友達リスト、投稿、写真、ページのいずれも取得しません。",
    "imp.fb4": "これらのデータは<b>第三者に提供せず</b>、広告にも使わず、AI・機械学習モデルの学習にも使いません。",
    "imp.fb5": "このサイトでは <b>Facebook のスクリプトもピクセルも動作していません</b>。サインインはボタンを押したときに初めて始まるリダイレクトで、それまで Facebook はあなたの訪問とは無関係です。",
    "imp.fbNote": "Facebook の設定で pumpfoil.org を削除すると、連携は自動的に解除されます。Pumpfoil アカウント自体は残ります。申請の状況は<a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">データ削除</a>のページで確認でき、アカウントの完全な削除はいつでもプロフィールから自分で行えます。",
    "imp.aiTitle": "AI の利用（Anthropic Claude）",
    "imp.aiIntro": "分析および開発のため、Anthropic の AI アシスタント Claude を利用しています。セッションデータや生データ、フィードバック、チャットのメッセージ（ダイレクトメッセージを含む）が Anthropic に送信され、次の目的で処理される場合があります。",
    "imp.ai1": "個々のセッションの分析（不具合の調査、妥当性の確認）",
    "imp.ai2": "当方の検出モデルの改善（ポンプおよびオンフォイルの検出）",
    "imp.ai3": "アプリの改良",
    "imp.ai4": "カタログに不足しているフォイルおよびスタビライザーの調査",
    "imp.aiNote": "Anthropic は当方の委託に基づき内容を処理します。適用される API 規約により、同社の言語モデルの学習には使用されません。処理は米国で行われる場合があります。アシスタントはチャットで自身の名前（アカウント「Claude Code AI」）で返信することがあります。詳細は Anthropic の <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">プライバシーポリシー</a>.",
    "account.gpsSparen": "ストレージ節約：走行の前後だけ記録",
    "account.gpsSparenHint": "時速6 km以上で動いている間だけ、その前後30秒を含めてGPSとモーションデータを保存します。泳いでいる時間、待ち時間、歩いて戻る時間は保存しません。ラン、パンプ数、フォイル時間はほぼ変わりません（141セッションで検証：フォイル時間 −0.15 %、パンプ −0.3 %）。地図ではラン同士の間の移動だけが表示されなくなります。",
    "account.gpsSparenUhr": "このウォッチ：計測した保存容量は約{kb} KB。{modus}では、節約なしで約{ohne}分、節約ありで通常{von}〜{bis}分記録できます（時速6 km未満の時間の長さによります）。",
    "account.gpsSparenUhrUnbekannt": "このウォッチの保存容量の上限はまだ計測されていません。たいていは十分な空きがあるということです。節約しても問題はありませんが、効果は小さいです。",
    "account.gpsSparenNotfall": "記録中に空き容量が少なくなると（100 KB未満）、ウォッチが自動で節約をオンにし、それ以降はGPSだけを保存します。記録は続き、ランも引き続き認識されますが、その時点からパンプ数は記録されません。",
    "account.gpsSparenAus": "地図に全ルートが必要な場合はオフにしてください。ウォッチのバージョン1.0.92以降で有効です。",
