    "imp.hostTitle": "服务器与托管",
    "imp.host1": "pumpfoil.org 的服务器由 <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> 运营。该公司的总经理即本项目的运营者；SmartKomm <b>免费</b>提供服务器。",
    "imp.host2": "服务器托管于 <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>。我们与 Hetzner 签订了<b>符合 GDPR 第 28 条的数据处理协议</b>。",
    "imp.fbTitle": "Facebook 登录（“继续使用 Facebook”）",
    "imp.fbIntro": "如果你使用 Facebook 账号登录，我们仅处理以下数据：",
    "imp.fb1": "<b>获取：</b>你的电子邮箱地址、你的名字和你的 Facebook 用户 ID。我们不获取姓氏和头像。",
    "imp.fb2": "<b>用途：</b>仅用于创建和登录你的 Pumpfoil 账号，以及在应用中显示你的名字。",
    "imp.fb3": "我们<b>不访问</b>任何其他 Facebook 数据——不读取好友列表、帖子、照片或主页。",
    "imp.fb4": "这些数据<b>不会提供给第三方</b>，不用于广告，也不用于训练人工智能或机器学习模型。",
    "imp.fb5": "本网站<b>不运行任何 Facebook 脚本或像素代码</b>。登录只是一次跳转，只有在你按下按钮时才会开始；在此之前，Facebook 与你的访问无关。",
    "imp.fbNote": "如果你在 Facebook 设置中移除 pumpfoil.org，我们会自动删除关联，你的 Pumpfoil 账号会保留。此类请求的状态可在<a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">数据删除</a>页面查看；如需彻底删除账号，你随时可以在个人资料中自行操作。",
    "imp.aiTitle": "AI 支持（Anthropic Claude）",
    "imp.aiIntro": "为进行分析与开发，我们使用 Anthropic 的 AI 助手 Claude。会话数据与原始数据、反馈以及聊天消息（包括私信）可能会传输至 Anthropic 并在该处处理，用于以下目的：",
    "imp.ai1": "分析单次会话（排查故障、合理性检查）",
    "imp.ai2": "改进我们的识别模型（打水与在板识别）",
    "imp.ai3": "继续开发应用",
    "imp.ai4": "查找目录中缺失的前翼与稳定翼",
    "imp.aiNote": "Anthropic 受我们委托处理相关内容；依据适用的 API 条款，这些内容不会用于训练其语言模型。处理可能在美国进行。助手可能以自己的名义在聊天中回复（账号“Claude Code AI”）。详见 Anthropic 的 <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">隐私政策</a>.",
    "account.gpsSparen": "节省存储：只记录滑行前后",
    "account.gpsSparenHint": "手表只在你的速度超过 6 km/h 时保存 GPS 和运动数据，并包含之前和之后各 30 秒。游泳、等待和走回去的时间不会保存。滑行段、泵动次数和水翼时间基本不变（在 141 个记录上验证：水翼时间 −0.15 %，泵动 −0.3 %）；地图上只缺少滑行段之间的路线。",
    "account.gpsSparenUhr": "这块手表：实测存储约 {kb} KB。在{modus}模式下，不节省约可记录 {ohne} 分钟，节省后通常可记录 {von}–{bis} 分钟——取决于你慢于 6 km/h 的时间有多长。",
    "account.gpsSparenUhrUnbekannt": "这块手表还没有测得存储上限——通常说明空间很充足。开启节省没有坏处，但这里作用不大。",
    "account.gpsSparenNotfall": "如果记录过程中存储快满了（剩余不足 100 KB），手表会自动开启节省，此后只保存 GPS。记录会继续，滑行段仍会被识别，但从那时起没有泵动数据。",
    "account.gpsSparenAus": "如果你需要在地图上看到完整路线，请关闭。适用于手表版本 1.0.92 及以上。",
    "account.sparModusFull": "25 Hz（含运动数据）",
