    "account.viewsKlassikHint": "Эти часы не могут показывать ваши собственные макеты: {names}. Вместо макета они показывают его первые три значения сверху вниз, каждое с названием поля. Классические страницы выглядят точно так, как вы их настроили.",
    "account.viewsLiteHint": "У этих часов очень мало памяти: {names}. Собственные макеты они показывают как первые три значения. Между заездами и в паузе они показывают только первую страницу и всегда перелистывают все страницы.",
