    "sd.mergeShareGone": "Одна из объединённых записей была доступна по ссылке — эта ссылка больше не работает. Поделись объединённой записью заново, если хочешь.",
    "sd.mergeShareGoneN": "{n} объединённых записей были доступны по ссылкам — эти ссылки больше не работают. Поделись объединённой записью заново, если хочешь.",
