    "imp.hostTitle": "Сервер и хостинг",
    "imp.host1": "Сервер pumpfoil.org обслуживает <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b>. Её управляющий директор — владелец этого проекта; SmartKomm предоставляет сервер <b>безвозмездно</b>.",
    "imp.host2": "Сервер размещён у <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. С Hetzner заключён <b>договор об обработке данных по ст. 28 GDPR</b>.",
    "imp.fbTitle": "Вход через Facebook («Продолжить через Facebook»)",
    "imp.fbIntro": "Если ты входишь через свой аккаунт Facebook, мы обрабатываем исключительно следующие данные:",
    "imp.fb1": "<b>Доступ:</b> твой адрес электронной почты, твоё имя и твой идентификатор пользователя Facebook. Фамилию и фотографию профиля мы не запрашиваем.",
    "imp.fb2": "<b>Использование:</b> исключительно для создания аккаунта Pumpfoil и входа в него, а также для показа твоего имени в приложении.",
    "imp.fb3": "<b>Нет доступа</b> к другим данным Facebook — ни к списку друзей, ни к публикациям, ни к фотографиям, ни к страницам.",
    "imp.fb4": "Эти данные <b>не передаются третьим лицам</b>, не используются для рекламы и не используются для обучения моделей ИИ или машинного обучения.",
    "imp.fb5": "На этом сайте не работает <b>ни один скрипт Facebook и ни один пиксель</b>. Вход — это перенаправление, которое запускается только после нажатия кнопки; до этого Facebook не имеет отношения к твоему визиту.",
    "imp.fbNote": "Если ты удалишь pumpfoil.org в настройках Facebook, мы автоматически удалим связь; твой аккаунт Pumpfoil останется. Состояние такого запроса можно посмотреть на странице <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Удаление данных</a>, а полностью удалить аккаунт ты можешь в любой момент сам в профиле.",
    "imp.aiTitle": "Помощь ИИ (Anthropic Claude)",
    "imp.aiIntro": "Для анализа и разработки мы используем ИИ-ассистента Claude от Anthropic. Данные сессий и «сырые» данные, отзывы и сообщения чата — в том числе личные сообщения — могут передаваться в Anthropic и обрабатываться там в следующих целях:",
    "imp.ai1": "анализ отдельных сессий (поиск ошибок, проверка достоверности)",
    "imp.ai2": "улучшение наших моделей распознавания (пампинг и движение на фойле)",
    "imp.ai3": "дальнейшая разработка приложения",
    "imp.ai4": "поиск отсутствующих фойлов и стабилизаторов для каталога",
    "imp.aiNote": "Anthropic обрабатывает содержимое по нашему поручению; согласно действующим условиям API оно не используется для обучения их языковых моделей. Обработка может происходить в США. Ассистент может отвечать в чате под своим именем (аккаунт «Claude Code AI»). Подробнее — в <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">политике конфиденциальности Anthropic</a>.",
    "account.gpsSparen": "Экономия памяти: записывать только вокруг заездов",
    "account.gpsSparenHint": "Часы сохраняют GPS и данные движения, только пока ты движешься быстрее 6 км/ч, плюс 30 секунд до и после. Плавание, ожидание и возвращение пешком не сохраняются. Заезды, пампы и время на фойле практически не меняются (проверено на 141 сессии: время на фойле −0,15 %, пампы −0,3 %); на карте не хватает только пути между заездами.",
    "account.gpsSparenUhr": "Эти часы: измеренная память около {kb} КБ. В режиме «{modus}» без экономии её хватает примерно на {ohne} минут, с экономией — обычно на {von}–{bis} минут, в зависимости от того, сколько времени ты медленнее 6 км/ч.",
    "account.gpsSparenUhrUnbekannt": "Для этих часов предел памяти ещё не измерен — обычно это значит, что места достаточно. Экономия не помешает, но здесь даёт мало.",
    "account.gpsSparenNotfall": "Если во время записи память заканчивается (свободно меньше 100 КБ), часы сами включают экономию и дальше сохраняют только GPS. Запись продолжается, и заезды по-прежнему распознаются, но с этого момента без пампов.",
    "account.gpsSparenAus": "Выключи, если нужен полный трек на карте. Действует с версии часов 1.0.92.",
