    "friends.terms": "Друзья видят всю твою страницу профиля, в том числе разделы, скрытые в профиле, и твой вес. Когда ты пампишь, они видят, на каком споте, и получают уведомление, даже если ты скрыл себя на карте спотов. Ты видишь то же самое у них. Скрытые места остаются скрытыми, твои сырые данные остаются личными. Дружбу можно прекратить в любой момент, другой человек не получит уведомления.",
