    "hideloc.hint": "Без галочки: твои записи остаются видимыми — только не то, где ты катался. Все, кроме тебя и твоих друзей, увидят тогда на карте и в названии спота Point Nemo, посреди Тихого океана. Там никто не пампит, и это сразу видно.",
