    "imp.hostTitle": "Server og hosting",
    "imp.host1": "Serveren til pumpfoil.org drives av <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b>. Daglig leder der er den som driver dette prosjektet; SmartKomm stiller serveren til rådighet <b>vederlagsfritt</b>.",
    "imp.host2": "Serveren står hos <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Med Hetzner er det inngått en <b>databehandleravtale etter art. 28 GDPR</b>.",
    "imp.fbTitle": "Facebook-innlogging («Fortsett med Facebook»)",
    "imp.fbIntro": "Hvis du logger inn med Facebook-kontoen din, behandler vi utelukkende disse dataene:",
    "imp.fb1": "<b>Tilgang:</b> e-postadressen din, fornavnet ditt og Facebook-bruker-ID-en din. Etternavn og profilbilde henter vi ikke.",
    "imp.fb2": "<b>Bruk:</b> utelukkende for å opprette og logge inn på Pumpfoil-kontoen din og for å vise fornavnet ditt i appen.",
    "imp.fb3": "Det er <b>ingen tilgang</b> til andre Facebook-data — ingen vennelister, ingen innlegg, ingen bilder, ingen sider.",
    "imp.fb4": "Disse dataene blir <b>ikke delt med tredjeparter</b>, ikke brukt til reklame og ikke brukt til å trene KI-/ML-modeller.",
    "imp.fb5": "På dette nettstedet kjører <b>ingen Facebook-skript og ingen piksel</b>. Innloggingen er en videresending som først starter når du trykker på knappen — før det har Facebook ingenting med besøket ditt å gjøre.",
    "imp.fbNote": "Fjerner du pumpfoil.org i Facebook-innstillingene dine, sletter vi koblingen automatisk; Pumpfoil-kontoen din blir værende. Status for en slik forespørsel finner du på <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Sletting av data</a>, og du kan slette kontoen helt selv når som helst i profilen.",
    "imp.aiTitle": "KI-støtte (Anthropic Claude)",
    "imp.aiIntro": "Til analyse og utvikling bruker vi KI-assistenten Claude fra Anthropic. Økt- og rådata, tilbakemeldinger og chatmeldinger — også direktemeldinger — kan overføres til Anthropic og behandles der, til disse formålene:",
    "imp.ai1": "analyse av enkelte økter (feilsøking, plausibilitetssjekk)",
    "imp.ai2": "forbedring av deteksjonsmodellene våre (pump- og on-foil-deteksjon)",
    "imp.ai3": "videreutvikling av appen",
    "imp.ai4": "research av manglende foiler og stabilisatorer til katalogen",
    "imp.aiNote": "Anthropic behandler innholdet på vårt oppdrag; etter gjeldende API-vilkår brukes det ikke til å trene språkmodellene deres. Behandlingen kan skje i USA. Assistenten kan svare i chatten under eget navn (kontoen «Claude Code AI»). Se <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">personvernerklæringen til Anthropic</a>.",
    "account.gpsSparen": "Spar lagring: lagre bare rundt øktene",
    "account.gpsSparenHint": "Klokka lagrer GPS og bevegelsesdata bare mens du er raskere enn 6 km/t, med 30 sekunder før og etter. Svømming, venting og gåing tilbake lagres ikke. Runs, pumps og foiltid blir praktisk talt de samme (sjekket på 141 økter: foiltid −0,15 %, pumps −0,3 %); på kartet mangler bare veien mellom runsene.",
    "account.gpsSparenUhr": "Denne klokka: målt lagring på omtrent {kb} KB. Med {modus} holder det i omtrent {ohne} minutter uten sparing, og vanligvis {von}–{bis} minutter med sparing – avhengig av hvor mye tid du er saktere enn 6 km/t.",
    "account.gpsSparenUhrUnbekannt": "Det er ennå ikke målt noen lagringsgrense for denne klokka – som regel betyr det at den har god plass. Sparing skader ikke, men gir lite her.",
    "account.gpsSparenNotfall": "Blir lagringen knapp under opptaket (under 100 KB ledig), slår klokka på sparing selv og lagrer derfra bare GPS. Opptaket fortsetter og runs gjenkjennes fortsatt, men fra da av uten pumps.",
    "account.gpsSparenAus": "Slå av hvis du trenger hele sporet på kartet. Gjelder fra klokkeversjon 1.0.92.",
