    "kunst.regeln": "W każdej rundzie liczą się tylko twoje własne sesje nagrane w tej rundzie, wszystkie sporty, także na lądzie.\nRysowane jest tylko to, co przepłynąłeś na foilu. Można łączyć kilka przejazdów, ale tylko następujące po sobie z tej samej sesji.\nKażdy zgłasza jeden obraz na rundę i może go zmienić lub wycofać do końca rundy.\nObrazy innych są widoczne dopiero od głosowania.\nPo rundzie odbywa się głosowanie: anonimowo, widać tylko linię, każdy ma 3 serca i żadnego dla własnego obrazu.\nKto ma ile serc, okazuje się dopiero po głosowaniu — wtedy z imieniem i spotem (chyba że jest ukryty).\nHumor jest mile widziany. Usuwane jest tylko to, co naprawdę zabronione; rider widzi powód.",
