    "imp.hostTitle": "Servidor e alojamento",
    "imp.host1": "O servidor do pumpfoil.org é operado pela <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b>. O seu gerente é o responsável por este projeto; a SmartKomm cede o servidor <b>gratuitamente</b>.",
    "imp.host2": "O servidor está alojado na <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b>. Existe com a Hetzner um <b>acordo de subcontratação nos termos do art. 28.º do RGPD</b>.",
    "imp.fbTitle": "Início de sessão com Facebook (“Continuar com o Facebook”)",
    "imp.fbIntro": "Se iniciares sessão com a tua conta do Facebook, tratamos exclusivamente os seguintes dados:",
    "imp.fb1": "<b>Acesso:</b> o teu endereço de e-mail, o teu primeiro nome e o teu ID de utilizador do Facebook. Não obtemos apelido nem fotografia de perfil.",
    "imp.fb2": "<b>Utilização:</b> exclusivamente para criar e aceder à tua conta Pumpfoil e para mostrar o teu primeiro nome na aplicação.",
    "imp.fb3": "<b>Não há acesso</b> a quaisquer outros dados do Facebook — nem lista de amigos, nem publicações, nem fotografias, nem páginas.",
    "imp.fb4": "Estes dados <b>não são partilhados com terceiros</b>, não são usados para publicidade e não são usados para treinar modelos de IA ou de aprendizagem automática.",
    "imp.fb5": "Neste site não corre <b>nenhum script do Facebook nem pixel</b>. O início de sessão é um reencaminhamento que só arranca quando carregas no botão — antes disso, o Facebook nada tem a ver com a tua visita.",
    "imp.fbNote": "Se removeres o pumpfoil.org nas definições do Facebook, eliminamos a ligação automaticamente; a tua conta Pumpfoil mantém-se. O estado desse pedido está em <a href=\"/datenloeschung\" class=\"text-brand-400 hover:underline\">Eliminação de dados</a>, e podes eliminar a tua conta por completo a qualquer momento no perfil.",
    "imp.aiIntro": "Para análise e desenvolvimento usamos o assistente de IA Claude da Anthropic. Dados de sessão e em bruto, feedback e mensagens de conversa — incluindo mensagens diretas — podem ser transmitidos à Anthropic e processados lá, para estas finalidades:",
    "imp.ai1": "análise de sessões individuais (deteção de erros, verificação de plausibilidade)",
    "imp.ai2": "melhoria dos nossos modelos de deteção (pump e on-foil)",
    "imp.aiNote": "A Anthropic processa os conteúdos por nossa conta; segundo os termos de API aplicáveis, não são usados para treinar os seus modelos de linguagem. O processamento pode ocorrer nos EUA. O assistente pode responder na conversa com nome próprio (conta «Claude Code AI»). Ver a <a href=\"https://www.anthropic.com/legal/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">política de privacidade da Anthropic</a>.",
    "account.gpsSparen": "Poupar memória: gravar só em torno das sessões",
    "account.gpsSparenHint": "O relógio grava GPS e dados de movimento apenas enquanto vais acima de 6 km/h, com 30 segundos antes e depois. Nadar, esperar e voltar a pé não são gravados. Runs, pumps e tempo em foil ficam praticamente iguais (verificado em 141 sessões: tempo em foil −0,15 %, pumps −0,3 %); no mapa falta apenas o caminho entre os runs.",
    "account.gpsSparenUhr": "Este relógio: memória medida de cerca de {kb} KB. Em {modus}, isso dá para cerca de {ohne} minutos sem poupança e, com poupança, normalmente para {von}–{bis} minutos – conforme o tempo que passas abaixo de 6 km/h.",
    "account.gpsSparenUhrUnbekannt": "Ainda não medimos o limite de memória deste relógio – normalmente significa que tem bastante espaço. Poupar não prejudica, mas aqui ajuda pouco.",
    "account.gpsSparenNotfall": "Se a memória ficar escassa durante a gravação (menos de 100 KB livres), o relógio ativa a poupança sozinho e a partir daí grava só o GPS. A gravação continua e os runs continuam a ser reconhecidos, mas a partir desse ponto sem pumps.",
    "account.gpsSparenAus": "Desativa se precisares do percurso completo no mapa. Válido a partir da versão 1.0.92 do relógio.",
