// Kroatisch-Overlay (hr, Hrvatski; aus web/src/i18n/locales/hr.ts + app-eigene Keys aus dem
// Englischen, 25.11.2026). 1354 Keys — dieselben wie nb (plus rec.carves180 aus pl). Fallback: Englisch (Loc.t).
// In Bloecke zu hoechstens 50 Eintraegen zerlegt wie die anderen Overlays — EIN Riesen-Literal laesst
// den Swift-Type-Checker im Release-Build minutenlang kauen.
let hrOverlay: [String: String] = {
    var d: [String: String] = [:]
    for p in [_hrOverlayP1, _hrOverlayP2, _hrOverlayP3, _hrOverlayP4, _hrOverlayP5, _hrOverlayP6, _hrOverlayP7, _hrOverlayP8, _hrOverlayP9, _hrOverlayP10, _hrOverlayP11, _hrOverlayP12, _hrOverlayP13, _hrOverlayP14, _hrOverlayP15, _hrOverlayP16, _hrOverlayP17, _hrOverlayP18, _hrOverlayP19, _hrOverlayP20, _hrOverlayP21, _hrOverlayP22, _hrOverlayP23, _hrOverlayP24, _hrOverlayP25, _hrOverlayP26, _hrOverlayP27, _hrOverlayP28] { d.merge(p) { a, _ in a } }
    return d
}()

