    "imp.googleNote": "A Google API-kból származó információk felhasználása megfelel a <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a> irányelveinek, beleértve a korlátozott felhasználásra (Limited Use) vonatkozó követelményeket.",
    "imp.googleTitle": "Google-bejelentkezés (Google-felhasználói adatok)",
    "imp.host1": "A pumpfoil.org szervert a <b><a href=\"https://smartkomm.de/\" target=\"_blank\" rel=\"noopener noreferrer\">SmartKomm GmbH</a></b> üzemelteti. Ügyvezetője a projekt üzemeltetője; a SmartKomm <b>ingyenesen</b> biztosítja a szervert.",
    "imp.host2": "A szervert a <b><a href=\"https://www.hetzner.com\" target=\"_blank\" rel=\"noopener noreferrer\">Hetzner Online GmbH</a></b> üzemelteti. A Hetznerrel <b>a GDPR 28. cikke szerinti adatfeldolgozási szerződés</b> van érvényben.",
    "imp.hostTitle": "Szerver és tárhely",
    "imp.intro": "Ez az alkalmazás egy közösség: a foil-edzéseket megosztjuk másokkal. Itt pontosan látod, melyik adat kinek látható.",
    "imp.map1": "Az <b>utcatérkép</b> az <b>OpenStreetMap</b>-től származik. Amikor egy térkép megjelenik, a böngésződ közvetlenül az ő szervereikről tölti be a térképcsempéket, ami továbbítja az IP-címedet és a megtekintett részletet. Szolgáltató: OpenStreetMap Foundation, Egyesült Királyság.",
    "imp.map2": "Ha a térképen lévő gombbal <b>Műhold</b> nézetre váltasz, a légifelvételek az <b>Esri</b>-től (Esri, Maxar, Earthstar Geographics) származnak — szintén közvetlenül az ő szervereikről, és szintén az IP-címeddel. Ez <b>csak</b> akkor történik, ha váltasz; a választásodat helyben, az eszközödön jegyezzük meg.",
    "imp.mapApple": "Az <b>iPhone- és Apple Watch-alkalmazásban</b> a térkép és a légifelvételek is az <b>Apple Térképek</b>-től származnak, nem az OpenStreetMaptől vagy az Esritől. Egy térkép megjelenítése elküldi a megjelenített területet az Apple-nek; ezért az Apple felel a saját adatvédelmi irányelvei szerint. Az <b>Android-alkalmazás</b> úgy működik, mint a böngésző: utcatérkép az OpenStreetMaptől, légifelvételek az Esritől.",
    "imp.mapTitle": "Térképek",
    "imp.operator1": "E-mail-címek, minden nyers adat, eszközkapcsolatok és technikai szervernaplók.",
    "imp.operator2": "A jelszavakat csak sózott hash-ként (PBKDF2) tároljuk — még én sem látom őket nyílt szövegként.",
    "imp.operatorTitle": "🛠 Csak az üzemeltető (Jan)",
    "imp.owner1": "Az edzéseid <b>nyers adatai</b> (egyes GPS-pontok, 25 Hz-es gyorsulás) — pl. címkézéshez.",
    "imp.owner2": "Címkék, levágás, újraelemzés, fotók feltöltése/törlése.",
    "imp.owner3": "Az <b>e-mail-címed</b> és a fiókbeállításaid — soha nem láthatók más felhasználók számára.",
    "imp.owner4": "Csak te látod, ki kedvelte az edzésedet; mások csak a számot látják. Hogy ki jelentette „hamisnak tűnik” vagy „nem megfelelő” jelzéssel, azt senkinek nem mutatjuk.",
    "imp.ownerTitle": "🔒 Csak te (az edzés tulajdonosa)",
    "imp.privacyText": "Minden feltöltött adatot tartósan tárolunk. A törléshez használd a profilodban (webalkalmazás vagy iOS/Android-alkalmazás) a „Fiók törlése” gombot — ez véglegesen eltávolítja a fiókodat az összes edzéssel, nyers adattal és fotóval együtt. Az átvitel titkosított (HTTPS).",
    "imp.privacyTitle": "Adattörlés",
    "imp.public1": "<b>Feltöltött fotók</b> és <b>profilképek</b>: a képfájlok egy véletlenszerű, kitalálhatatlan link alatt vannak. Aki ismeri ezt a linket (pl. továbbították neki), fiók nélkül is megnyithatja a képet. A fotók EXIF/GPS-adatait feltöltéskor eltávolítjuk.",
